import{_ as r}from"./chunks/224e934212c1aeba6bf2.D6ktk5St.js";import{_ as o,C as a,o as l,c as n,j as t,a as i,E as s,a5 as h}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"创作者经济中当下最赚钱的细分领域","description":"","frontmatter":{"title":"创作者经济中当下最赚钱的细分领域","originalTitle":"The Most Profitable Niche In The Creator Economy Right Now","date":"2025-05-15","originalUrl":"https://thedankoe.com/letters/the-most-profitable-niche-in-the-creator-economy-right-now/","minutes":12,"sourceHash":"d2ce84605d3486fae70b312b4280997243135a1097444f42b4e37f7892d87233","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-most-profitable-niche-in-the-creator-economy-right-now/"}]]},"headers":[],"relativePath":"letters/the-most-profitable-niche-in-the-creator-economy-right-now.md","filePath":"letters/the-most-profitable-niche-in-the-creator-economy-right-now.md"}'),c={name:"letters/the-most-profitable-niche-in-the-creator-economy-right-now.md"};function m(g,e,u,d,f,_){const p=a("ArticleMeta");return l(),n("div",null,[e[0]||(e[0]=t("h1",{id:"创作者经济中当下最赚钱的细分领域",tabindex:"-1"},[i("创作者经济中当下最赚钱的细分领域 "),t("a",{class:"header-anchor",href:"#创作者经济中当下最赚钱的细分领域","aria-label":'Permalink to "创作者经济中当下最赚钱的细分领域"'},"​")],-1)),s(p),e[1]||(e[1]=h('<p><a href="https://www.youtube.com/embed/6Q_1QJsO4Ro?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>最赚钱的细分领域就是你自己。</p><p>至少这是我三年前说的话，结果引来了一堆爱与恨。</p><p>我收到过很多评论和私信，说他们“感觉被看见了”。我在现实生活中也遇到过一些人，告诉我正是这个理念促使他们开始在网上分享自己的想法。“你就是细分领域”这句话被写进了我的<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">第一本书</a>，并塑造了我对待有意义工作的方式。</p><p>但另一面也存在。</p><p>似乎每隔一天，我就会看到一篇帖子、一段视频或一份通讯，标题是“你<strong>不是</strong>细分领域”。</p><p>当我读到或看到这些内容时，我忍不住笑出声，因为这暴露出他们只读了我那句话“你就是细分领域”，就立刻做出反应，根本没做认真的研究，或者他们压根没理解我在说什么。</p><p>大多数人其实不自觉地就认同了我的观点。</p><p>就拿达科塔（Dakota）来说吧，我在德克萨斯州奥斯汀和他一起住过六个月的好朋友。</p><p><img src="'+r+'" alt=""></p><p>我全心全意地爱达科塔，但这只是半真半假的说法。</p><p>我确实提供网页设计的<strong>产品和服务</strong>，但我的内容中只有大约5%和网页设计有关。从任何角度来看，如果你回头翻看我2019年及以后的推文，你会发现大多数帖子都是关于自我提升、情商、生产力，以及其他我觉得有趣的东西。</p><p>我本可以（也确实）提供其他任何产品或服务，而不仅仅是网页设计，并且同样能做得很好。这一点我很有信心。</p><p>正如我们将会发现的那样，你<strong>完全不必</strong>先从窄领域起步，再逐渐拓宽。</p><p>我制作那个“你就是细分领域”视频的全部原因，就是因为我厌倦了人们把商业当成一种宗教来对待。</p><p><em>如果你不遵从商业<strong>应该</strong>是什么样子，你永远都不会成功！</em></p><p>所以，这正是我想在这里做的事。</p><p>我想彻底终结这场争论。</p><p>而不是再说“最赚钱的细分领域就是你自己”，我打算给出一种完全不同的思路。</p><p>如果你对从何处开始感到迷茫，这可能会彻底改变一切。</p><h2 id="以主题为基础-vs-以使命为基础" tabindex="-1">以主题为基础 vs 以使命为基础 <a class="header-anchor" href="#以主题为基础-vs-以使命为基础" aria-label="Permalink to &quot;以主题为基础 vs 以使命为基础&quot;">​</a></h2><p>我把那种“传统”的细分方式称为<strong>以主题为基础。</strong></p><p>简单来说，你选择一个目标受众和一个主题，比如写作或网页设计，去帮助那个目标受众，比如为建筑工人提供网页设计服务。再配上一个迫切的问题，你就上路了。你也可以单独细分目标受众，但当人们教授社媒创业方法时，他们通常指的是选择一个主要主题来建立权威性。</p><p>我理解这一点。</p><p>你不需要花太多心思去想该创作什么内容。变现方式非常清晰，你可以很快实现变现。你可以成为你那个细分领域里的“首选”人物。</p><p>但我对这种路线有以下几个大不满：</p><ul><li><strong>你被困在那个细分领域里。</strong>如果你失败了，或者当<strong>你</strong>这个人发生了变化（这是必然的）而想要转型，你会过得很糟糕。这是反持续学习、反博学者、反人性的。</li><li><strong>它鼓励人们去寻找“最好”或最赚钱的领域。</strong>大多数人放弃是因为他们换了20次细分领域，因为他们一开始创业的理由就是错的。只要你真的擅长自己所做的事，任何细分领域都能行得通。（参见：能力问题）</li><li><strong>它把多重兴趣的人撕得支离破碎。</strong>有多重兴趣的人不需要被告知只能选<strong>一个</strong>。他们需要学会如何把所有兴趣都汇聚成一件事。如果你对多件事感兴趣，别人也可能如此，而你已经在关注很多谈论不止一个话题的成功人士了。睁大眼睛看看。</li></ul><p>如你所见，我写这篇文章是因为我讨厌被塞进一个框里的想法。</p><p>我不想让商业变成另一份让我醒来后最终厌恶的工作。我想让工作成为我生活中自然的一部分。我想让它成为一种游戏。我想让它成为我学习想学的东西、建造想建的东西、创造想创造的东西的载体。</p><p><strong>这就引出了更好的细分方式，我称之为</strong><em><strong>以使命为基础。</strong></em></p><p>当你在打造一个现代企业时，你其实是一家媒体企业。如果你不在社交媒体上，那你要么没在读这篇文章，要么就是在忽视必要的东西。</p><p>在社交媒体上，大多数人没有考虑到内容是如何被<strong>看见</strong>的。</p><p>他们怎么可能考虑到呢？他们是新手，不知道更好的方法。这没关系。</p><p>你的内容被别人看见，是因为别人分享了它（除此之外还有其他方式，但都不是关键因素）。</p><p>当你的内容被分享时，它是被分享给<strong>随机的人</strong>。</p><p>这不是付费广告，你不能输入想要定位的人群特征，让每一条广告都直接送到你要定位的细分领域。</p><p>这就是大多数新手失败的原因。因为他们不知道如何创作出足够吸引人去<strong>关注</strong>的内容。</p><p>那么，人们会关注谁呢？</p><p>领袖。</p><p>领袖有什么？</p><p>使命。</p><p>为什么这是更好的选择？</p><ul><li>商业成为你毕生事业的载体。</li><li>你可以谈论任何能推动人们朝那个使命前进的话题。</li><li>这是以转变为导向的。也就是说，创作内容是围绕痛点和期望结果展开的。</li><li>想出创意变得容易多了。任何你阅读、观看或听到的、在某种程度上与你的使命相符的想法，都可以被记录下来，并转化为你自己品牌下的创意。</li></ul><p>实际上，我昨天刚发布了<a href="https://open.substack.com/pub/thedankoe/p/3-drills-to-become-a-master-at-short?r=of0ip&amp;utm_campaign=post&amp;utm_medium=web&amp;showWelcomeOnShare=true" target="_blank" rel="noreferrer">3个练习，教你如何写出</a>基于任何想法都能吸引人的短内容。</p><p>如你所见，我最近把我的通讯重新命名为“未来/证明”（future/proof）。</p><p>那就是我的使命：帮助尽可能多的人在过上美好生活的同时，变得有价值、能适应变化。</p><p>为了实现这个使命，我几乎必须谈论商业的方方面面、生产力、自我实现、科技、各种技能，等等。我有整整<strong>十年</strong>的内容储备可以拿出来，去完成这个使命。</p><p>有段时间我感觉自己陷入了停滞。灵感不像以前那样源源不断地涌来。当我决定做出这个转变时，好的想法又开始大量涌入。几年前，当我有了帮助人们掌握现代世界的清晰使命时（也就是Modern Mastery，现已关闭），可以说那正是我最好作品诞生的时期，它也为我如今以一人企业为主题、广为人知的内容打下了基础。</p><p>关键在于，<em>两种选择都行得通。</em></p><p>迪基·布什（Dickie Bush）和尼古拉斯·科尔（Nicholas Cole）有一份名为Write With AI的通讯，走的是传统的细分路线。它做得非常好。</p><p>尽管我在很多方面都很欣赏他们（迪基，如果你在读这篇文章，我很期待和你再吃一次饭），但如果让我做类似的事，我可能宁愿自杀。</p><p>在“以主题为基础”和“以使命为基础”之间的选择，<strong>取决于个性。</strong></p><p>两者都拥有巨大的变现潜力。</p><p>但坦白说，了解<strong>我的</strong>受众之后，我认为以使命为基础是更好的方法。</p><p>尽管极端化的绝对观点在社交媒体上更容易走红，但其实这件事没有唯一正确的做法。见鬼，有些人根本没有任何计划就开始发帖，然后一夜成名。事实是，你可能（又一次）想得太多了，但了解我是如何思考这个问题的，能帮助你获得清晰感。</p><p><a href="https://thedankoe.substack.com/embed" target="_blank" rel="noreferrer">观看原文视频</a></p><h2 id="如何领导一项使命" tabindex="-1">如何领导一项使命 <a class="header-anchor" href="#如何领导一项使命" aria-label="Permalink to &quot;如何领导一项使命&quot;">​</a></h2><p>承认这一点让人有点难堪……</p><p>但你在网上关注某人的主要原因，是因为你渴望清晰感。</p><p>当我们发现一篇内容自信、有价值、并带着真实的两极分化立场时，你能感受到那位创作者身上的引力。感觉他们好像把一切都想清楚了，而我们也想拥有那种感觉。承认这一点没什么不好。</p><p>现在，我要第一手告诉你：其实没有人真正知道自己在做什么。</p><p>有些人只是对自己的“不知道”足够自信，愿意抛出那些更可能是错误的想法和建议。</p><p>许多深度思考者陷入了这种“细枝末节”的螺旋。他们把自己的想法撕得支离破碎，对自己所说的话毫无信念，把自己的思想稀释到<strong>反行动</strong>的程度。</p><p>“嗯，这不适用于这个人，这也<strong>不总是</strong>这样的”，等等等等。无聊。没人想读这种东西。</p><p>听我说：</p><ul><li>与其像风中的一片叶子那样随波逐流，倒不如坚信一个坏想法然后失败。至少你在犯错时能学到点东西。</li><li>一个好想法的意义在于激发行为改变。当你给予人们行动、失败、学习的信心和清晰感时，你所改变的生命，远比把自己“细枝末节”到死更多。</li><li>拥有自信，加上一点点夸张，能帮你把<strong>要点</strong>传达出去。如果人们没抓住重点，或者他们逐字理解而不是理解隐喻，那就随他们去。对你来说，那只是更多的曝光。</li></ul><p>这三点会比你得到的其他任何社交媒体建议都更能帮助你快速成长。做你自己，无怨无悔。</p><p>在我们继续之前，记住这些要点。</p><p>现在，拿出一张纸，或者打开你最喜欢的笔记应用，开始把这些记下来。</p><p>如果你下载了<a href="https://kortex.co/download" target="_blank" rel="noreferrer">Kortex桌面应用</a>，你可以用Option或Alt + D打开一个浮动便签（如果你想的话，还可以用Option或Alt + A打开一个浮动AI聊天）。</p><h3 id="_1-你需要一个可以攻击的敌人" tabindex="-1">1）你需要一个可以攻击的敌人 <a class="header-anchor" href="#_1-你需要一个可以攻击的敌人" aria-label="Permalink to &quot;1）你需要一个可以攻击的敌人&quot;">​</a></h3><p>回答这些问题：</p><ul><li>哪种生活方式是你存在的祸根？</li><li>你正在做什么来避免那种生活？</li><li>为什么它如此具有破坏性？</li></ul><p>出于某种原因，我一直都厌恶朝九晚五的工作。我知道这会让我落入那种老套的“朝九晚五讨厌者”阵营，尽管我其实并不是那样的人，但我就是做不到。似乎每个过着我不想要的生活的人，都陷入了那种境地，大多是因为他们有着漫长且令人厌恶的工作时间，这也耗尽了他们每天做任何有价值事情的精力。大多数人都是行走的僵尸。我不在乎那些例外者。<strong>大多数</strong>人就是这样。</p><p>这成为了我学习并竭尽全力去避免那种生活的驱动力。我想掌握现代世界。我想变得未来可期、不被时代淘汰。</p><h3 id="_2-创造一个供人们采用的身份" tabindex="-1">2）创造一个供人们采用的身份 <a class="header-anchor" href="#_2-创造一个供人们采用的身份" aria-label="Permalink to &quot;2）创造一个供人们采用的身份&quot;">​</a></h3><p>在你品牌“敌人”的另一面，是你想让人们成为的那种原型人物。</p><p>当你关注某人或购买某物时，其背后的根本原因，是你想成为某种人（或强化你认为自己已经是的那种人）。</p><p>人们关注你，不是因为他们喜欢你的想法。他们关注你，是因为你的想法能影响他们的行为，帮他们解决生活中阻碍他们发挥潜力的问题。</p><p>为你的使命命名，让它与此保持一致。</p><p>Modern Mastery（现代精通）传递出他们可以成为怎样的人的形象。</p><p>Future Proof（未来无忧）也暗示着同样的东西。</p><p>2-Hour Writer（两小时作家）也是如此。</p><p>一人企业、价值创造者，或者我任何一篇最热门的内容，始终都遵循这个模式。</p><p>为此头脑风暴出5到10个名字，然后放一放，让它们沉淀一晚。</p><p>它们不必成为你的产品名、社媒账号名或通讯名，除非你希望如此。它们只是你的指路明灯。</p><h3 id="_3-打造一个供人们探索的世界" tabindex="-1">3）打造一个供人们探索的世界 <a class="header-anchor" href="#_3-打造一个供人们探索的世界" aria-label="Permalink to &quot;3）打造一个供人们探索的世界&quot;">​</a></h3><p>你的细分领域并不是靠一句品牌宣言展示出来的。</p><p>“我帮____做____而不需要____”这种套路已经是过去的遗物了。</p><p>相反,你的细分领域是由你的作品体系,以及被它吸引来的人所展现出来的。</p><p>如今做生意,已经不再是靠倒计时器和销售漏斗了。它更像是在为人们打造一个可以探索的世界。就像一个小型的漫威电影宇宙,有电影(长内容)、衍生剧(短内容)、玩具人偶(产品),以及其他各种延伸。</p><p>你需要足够持续地更新,让人们可以在一周之内“刷完”你提供的所有内容,因为这就是现在人们消费内容的方式,也是你真正开始赚钱的时候。当你的某条帖子表现出色时,他们就会开始到处搜索更多信息,或者像YouTube这样的平台会继续把你之前的内容推给他们。</p><p>我在其中一个视频火起来之前,发了30到40个YouTube视频。之前,它们只有2000到3000的播放量。等一个视频火了之后,它们全都涨到了10万以上的播放量。<em>你现在发布的东西,即使当下表现不好,一旦你迎来增长爆发期,依然<strong>可能</strong>会被人看到。</em></p><p>如果你发了10次帖子就放弃了,你根本不知道这一切到底是怎么运作的。</p><p>我写过一篇关于用内容生态系统<a href="https://thedankoe.substack.com/p/how-to-build-a-world-the-2-hour-content" target="_blank" rel="noreferrer">“如何打造一个世界”的文章</a>,感兴趣的话可以去看看。</p><p>现在,你需要用聪明的方式去做这件事。以下是我会采取的做法:</p><ul><li>找3到5个和你想谈的话题类似的账号。</li><li>按最热门筛选他们的内容,记下他们5到10篇表现最好的内容。</li><li>用你自己的视角、朝着你自己的愿景,重新创作这些话题。</li><li>持续地融入基础知识。如果你谈写作,就教写作的基本功。大多数关注你的人都是初学者。</li><li>阅读非主流的书籍,关注那些有绝佳想法但不太出名的人。把这些想法拿来,为你自己的使命重新包装。</li></ul><p>当然,任何浮现在脑海中的想法都可以写。</p><p>学会如何包装这些想法非常有帮助,这样它们才能一直表现良好(即使内容本身很平淡)。我们会在下一篇通讯里聊这个话题。</p><h3 id="_4-80-讲-为什么-20-讲-怎么做" tabindex="-1">4) 80%讲“为什么”,20%讲“怎么做” <a class="header-anchor" href="#_4-80-讲-为什么-20-讲-怎么做" aria-label="Permalink to &quot;4) 80%讲“为什么”,20%讲“怎么做”&quot;">​</a></h3><p>大多数新手的内容之所以扑街,是因为:</p><ul><li>他们没有足够狠地戳中痛点</li><li>他们没有给人们一个<em>关注他们的理由</em></li></ul><p>说到底,人们不分享你的内容,是因为它没有触及他们的处境。它没有钻进他们的脑子里,让他们看到自己有实现某种可能的潜力。</p><p>没有人是刷社交媒体去读你的深度思考的。</p><p>他们也不是在刷社交媒体去学一项新技能。如果他们想学点什么,他们会主动去谷歌、ChatGPT或YouTube上搜索。他们不会登录社交时间线去寻找具体的信息。</p><p>他们只会在<em>你说服了他们为什么应该关心</em>之后,才会去关心你的深度思考或那项新技能。</p><p>没错,我一开始是从网页设计入手的,但我让人们<em>想要学习</em>网页设计的方式,是去谈论“为什么”:</p><ul><li>这是一项能赚钱的技能</li><li>对于想做点有创意事情的人来说,这非常棒</li><li>你可以用它来找一份更好的工作、开始接自由职业,或者为自己的生意搭建网站</li></ul><p>让我成长起来的,并不是网页设计这种听起来有点无聊的东西本身。而是我让人们关心它的能力。</p><p>所以,在你点击发送任何一篇内容之前,问问自己:</p><ul><li>他们为什么应该关心?</li><li>这解决了什么一个重大痛点?</li><li>这对普通人能带来多大的好处?</li></ul><p>最后一点是关键,因为记住,你的内容会被分享给网上的普通人看到,而不仅仅是你所选话题领域里的专家。</p><p>可执行的步骤或“价值”是次要的。它固然不错,但对于短内容来说,除非是新颖或鲜为人知的东西,通常并不那么重要。如果内容特别基础,那我会把它留到初学者向你寻求更多信息的时候(一门入门课程、一份指南、一个小软件,或任何数字产品)。</p><p>就先讲到这里。</p><p>我真诚地希望这对你有帮助。</p><p>——丹(Dan)</p><p>当你准备好了,以下是我能进一步帮助你的几种方式:</p><ul><li>最新的付费文章是3个练习,帮你练习写出吸引人的短内容。<a href="https://thedankoe.substack.com/" target="_blank" rel="noreferrer">你可以在这里查看所有可用的付费文章。</a></li><li>如果你想把所有AI模型集中在一个地方,快速引用文档和PDF,并使用25个以上预先搭建好的学习、写作、营销和规划工作流——<a href="https://kortex.co/" target="_blank" rel="noreferrer">在这里免费注册Kortex。</a></li><li>每周六,我都会向我个人邮件列表上17.5万以上的人发送一份关于我所有写作内容的高浓度精华总结。如果你也想收到,<a href="https://thedankoe.com/letters" target="_blank" rel="noreferrer">可以在这里加入。</a></li></ul><hr><p><a href="/en/letters/the-most-profitable-niche-in-the-creator-economy-right-now">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',120))])}const P=o(c,[["render",m]]);export{w as __pageData,P as default};
